/* Kontenblatt nach den bereitgestellten IKR-Lehrbuchseiten; Kontenwerte bleiben im gemeinsamen Journal. */
(function(root){
'use strict';
const B=root.BioCasa;
const names={
'800':'Eröffnungsbilanzkonto (EBK)','801':'Schlussbilanzkonto (SBK)','802':'Gewinn- und Verlustkonto (GuV)',
'057':'Gebäudeeinrichtungen','073':'Anlagen für Wärme-, Kälte- und chemische Prozesse sowie ähnliche Anlagen','076':'Verpackungsanlagen und -maschinen','082':'Werkzeuge, Werksvorrichtungen und Modelle, Prüf- und Messmittel','084':'Fuhrpark','085':'Sonstige Betriebsausstattung','086':'Büromaschinen, Organisationsmittel und Kommunikationsanlagen','087':'Büromöbel und sonstige Geschäftsausstattung','160':'Sonstige Finanzanlagen','200':'Rohstoffe/Fertigungsmaterial','202':'Hilfsstoffe','210':'Unfertige Erzeugnisse','220':'Fertige Erzeugnisse','240':'Forderungen aus Lieferungen und Leistungen','260':'Vorsteuer','269':'Übrige sonstige Forderungen','280':'Guthaben bei Kreditinstituten (Bank)','288':'Kasse','290':'Aktive Jahresabgrenzung','300':'Gezeichnetes Kapital (Stammkapital)','310':'Kapitalrücklage','340':'Jahresüberschuss/Jahresfehlbetrag','380':'Steuerrückstellungen','391':'Sonstige Rückstellungen für Gewährleistung','393':'Sonstige Rückstellungen für Verluste','420':'Kurzfristige Bankverbindlichkeiten','425':'Langfristige Bankverbindlichkeiten','440':'Verbindlichkeiten aus Lieferungen und Leistungen','480':'Umsatzsteuer','483':'Verbindlichkeiten gegenüber Finanzbehörden','489':'Übrige sonstige Verbindlichkeiten','490':'Passive Rechnungsabgrenzung','5000':'Umsatzerlöse für eigene Erzeugnisse','5081':'Miet- und Pachterlöse','5201':'Bestandsveränderungen an unfertigen Erzeugnissen und selbsterbrachten Leistungen','5202':'Bestandsveränderungen an fertigen Erzeugnissen','5410':'Sonstige Erlöse (z. B. aus Anlagenabgängen)','5480':'Erträge aus der Auflösung von Rückstellungen','5710':'Zinserträge','600':'Aufwendungen für Rohstoffe/Fertigungsmaterial','602':'Aufwendungen für Hilfsstoffe','604':'Aufwendungen für Verpackungsmaterial','605':'Aufwendungen für Energie','616':'Fremdinstandhaltung','620':'Löhne','630':'Gehälter','640':'Arbeitgeberanteil zur Sozialversicherung','652':'Abschreibungen auf Sachanlagen','655':'Außerplanmäßige Abschreibungen auf Sachanlagen','670':'Mieten, Pachten','671':'Leasing','673':'Gebühren','677':'Rechts- und Beratungskosten','680':'Büromaterial','687':'Werbung','690':'Versicherungsbeiträge','696':'Aufwendungen aus dem Abgang von Vermögensgegenständen','698':'Zuführungen zu Rückstellungen für Gewährleistung','751':'Zinsaufwendungen','770':'Gewerbesteuer','771':'Körperschaftsteuer'};
const title=id=>names[id]||B.byId[id]?.name||id;
const categories=[{id:'assets',title:'Aktiva',subtitle:'Vermögen · Klassen 0–2',types:['asset']},{id:'passives',title:'Passiva',subtitle:'Eigenkapital und Schulden · Klassen 3–4',types:['equity','liability']},{id:'expense',title:'Aufwendungen',subtitle:'GuV · Klassen 6–7',types:['expense']},{id:'revenue',title:'Erträge',subtitle:'GuV · Klasse 5',types:['revenue']}];
const openingAccounts=B.ACCOUNTS.filter(a=>a.opening&&['asset','liability','equity'].includes(a.type)&&!['160','260','290'].includes(a.id));
const openingKeys=a=>a.id==='280'?['bankStart','bankAmount']:a.id==='425'?['loanStart','loanAmount']:['o'+a.id+'s','o'+a.id+'v'];
function openingReady(input){return openingAccounts.every(a=>{const [side,value]=openingKeys(a);try{return input[side]===(a.type==='asset'?'debit':'credit')&&B.money(input[value])===a.opening;}catch{return false;}});}
function counterparts(lines,line){return [...new Set(lines.filter(l=>line.debit?l.credit>0:l.debit>0).map(l=>l.account))];}
function postingInfo(entry,line){return {entryId:entry.id,date:entry.date,reference:entry.reference,source:entry.source,counterAccounts:counterparts(entry.lines,line),context:root.BioCasaTutorials?.info(entry)?.story||entry.text};}
function model(state,id,{draft=[],draftDate='',draftText='',draftReference='',opening=undefined,rows=null,showOpening=true,openingSide=null}={}){
 const a=B.byId[id];if(!a)throw Error('Unbekanntes Konto.');
 const balance=['asset','liability','equity'].includes(a.type),normalDebit=['asset','expense'].includes(a.type),ab=opening===undefined?(balance?a.opening:0):opening;
 const journalRows=rows?[]:B.journal(state).flatMap(e=>e.lines.filter(l=>l.account===id).map(l=>({row:{side:l.debit?'d':'c',amount:l.debit||l.credit,label:'BC-'+String(e.id).padStart(4,'0')+' · '+e.date.slice(8,10)+'.'+e.date.slice(5,7)+'.'},info:postingInfo(e,l)})));
 const postings=rows||journalRows.map(x=>x.row),openingRows=balance&&showOpening?[{side:openingSide||(normalDebit?'d':'c'),amount:ab,label:'AB · Eröffnungsbilanz',opening:true}]:[],draftLines=draft.filter(l=>l.account===id),draftRows=draftLines.map(l=>({side:l.debit?'d':'c',amount:l.debit||l.credit,label:'Dein Entwurf',draft:true}));
 // Retain the original signature so display-only metadata does not invalidate
 // saved learner closures. No amounts or journal entries are changed here.
 const all=[...openingRows,...postings,...draftRows];
 const debit=B.sum(all.filter(r=>r.side==='d'),r=>r.amount),credit=B.sum(all.filter(r=>r.side==='c'),r=>r.amount),amount=Math.abs(debit-credit),side=debit>credit?'c':credit>debit?'d':'0';
 let hash=2166136261;for(const c of JSON.stringify([id,all]))hash=Math.imul(hash^c.charCodeAt(0),16777619);
 const displayPostings=postings.map((r,i)=>({...r,...(rows?{}:journalRows[i].info)})).sort((a,b)=>(a.date||'').localeCompare(b.date||'')||(a.entryId||0)-(b.entryId||0));
 const displayRows=[...openingRows.map(r=>({...r,label:'EBK',date:B.PERIOD.start,source:'opening',context:'Der Anfangsbestand wird aus der bestätigten Eröffnungsbilanz auf dieses Bestandskonto übertragen. Das Eröffnungsbilanzkonto (EBK) ist das Gegenkonto; es entsteht dadurch kein neuer Geschäftsvorfall.'})),...displayPostings,...draftRows.map((r,i)=>({...r,date:B.dateOK(draftDate)?draftDate:'',source:'draft',reference:draftReference,counterAccounts:counterparts(draft,draftLines[i]),context:draftText?'Dein noch nicht gebuchter Beleg: '+draftText:'Noch nicht gebuchter Entwurf. Beschreibe den betrieblichen Vorgang im Buchungstext.'}))];
 return {id,account:a,balance,rows:displayRows,debit,credit,amount,side,total:Math.max(debit,credit),signature:(hash>>>0).toString(36),hasDraft:all.some(r=>r.draft)};
}
function check(m,value,side){let amount=null;try{amount=B.money(value);}catch{}return amount===m.amount&&side===m.side;}
function closed(state,m){return !m.hasDraft&&(state.accountClosures||[]).some(c=>c[0]===m.id&&c[1]===m.signature&&c[2]===m.amount&&c[3]===m.side);}
function closing(m){return {counter:m.amount?(m.balance?'801':'802'):'0',counterSide:m.side==='d'?'c':m.side==='c'?'d':'0'};}
function checkClosing(m,{value,side,counter,counterSide}={}){const target=closing(m);return check(m,value,side)&&counter===target.counter&&counterSide===target.counterSide;}
function close(state,id,input={}){if(input.automatic)throw Error('Entscheide selbst über Saldo, Abschlussseite und Gegenbuchung.');const m=model(state,id);if(!checkClosing(m,input))return null;const next=B.clone(state);next.accountClosures=[...(next.accountClosures||[]).filter(c=>c[0]!==id),[id,m.signature,m.amount,m.side,input.counter,input.counterSide]];return next;}
function counterModel(state,m){
 const target=closing(m),proofs=state?(state.accountClosures||[]).filter(c=>closed(state,model(state,c[0]))).map(c=>model(state,c[0])):[m];
 const rows=proofs.filter(x=>x.amount&&closing(x).counter===target.counter).map(x=>({side:closing(x).counterSide,amount:x.amount,counterAccounts:[x.id],source:'closing',date:B.PERIOD.end,label:'Abschluss '+x.id,highlight:x.id===m.id,context:'Gegenbuchung zum geprüften Kontoabschluss. Der Betrag steht auf der gegenüberliegenden Kontoseite.'}));
 const debit=B.sum(rows.filter(r=>r.side==='d'),r=>r.amount),credit=B.sum(rows.filter(r=>r.side==='c'),r=>r.amount);
 return {id:target.counter,rows,debit,credit,total:Math.max(debit,credit),amount:0,side:'0',balance:target.counter==='801'};
}
function validate(value,state){if(!Array.isArray(value)||value.length>B.ACCOUNTS.length)throw Error('Ungültige Kontenabschlüsse.');const seen=new Set();return value.map(c=>{if(!Array.isArray(c)||![4,6].includes(c.length)||!B.byId[c[0]]||seen.has(c[0])||typeof c[1]!=='string'||!/^\w{1,10}$/.test(c[1])||!Number.isSafeInteger(c[2])||c[2]<0||!['d','c','0'].includes(c[3]))throw Error('Ungültiger Kontenabschluss.');seen.add(c[0]);return [...c];}).filter(c=>{const m=model(state,c[0]);return c[1]===m.signature&&c[2]===m.amount&&c[3]===m.side&&(c.length===4||(c[4]===closing(m).counter&&c[5]===closing(m).counterSide));});}
function practice(state,id){const deposit={side:'d',amount:20000,label:'Übung 1 · Einzahlung',source:'practice',date:B.PERIOD.year+'-10-02',counterAccounts:['288'],context:'Zusätzliche Übung: Christian zahlt 200 € aus der Barkasse auf das Bankkonto ein. Das Bankguthaben nimmt zu, der Kassenbestand nimmt ab. Diese Übungsbuchung gehört nicht zum Jahresjournal.'},repayment={side:id==='280'?'c':'d',amount:500000,label:'Übung 2 · Tilgung',source:'practice',date:B.PERIOD.year+'-10-03',counterAccounts:[id==='280'?'425':'280'],context:'Zusätzliche Übung: BioCasa überweist 5.000 € zur Tilgung eines bestehenden Bankdarlehens. Bankguthaben und Darlehensschuld nehmen ab. Es sind keine Zinsen enthalten. Diese Übungsbuchung gehört nicht zum Jahresjournal.'};return model(state,id,{rows:id==='280'?[deposit,repayment]:[repayment]});}
root.BioCasaAccounts=Object.freeze({names:Object.freeze(names),title,categories,openingAccounts,openingKeys,openingReady,model,check,closed,close,validate,practice,closing,checkClosing,counterModel});
})(globalThis);
